import{c as o,Q as r,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"元曲三百首","description":"","frontmatter":{"id":"yuanqu300","title":"元曲三百首","author":"任中敏","dynasty":"近代","cover":"/covers/yuanqu.jpg","sort":5,"literaryValue":"《元曲三百首》收录了元代关汉卿、马致远、白朴等戏曲大家的经典散曲和杂剧选段，展现了元曲的艺术魅力。"},"headers":[],"relativePath":"books/shici/yuanqu.md","filePath":"books/shici/yuanqu.md"}'),h={name:"books/shici/yuanqu.md"};function i(n,a,s,l,u,d){return r(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="元曲三百首" tabindex="-1">元曲三百首 <a class="header-anchor" href="#元曲三百首" aria-label="Permalink to &quot;元曲三百首&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>元曲是盛行于元代的一种文艺形式，包括杂剧和散曲，有时专指杂剧。杂剧，宋代以滑稽调笑为特点的一种表演形式，元代发展成戏曲形式。每本以四折为主，在开头或折间另加楔子。每折用同宫调同韵的北曲套曲和宾白组成。如关汉卿的《窦娥冤》等。流行于大都（今北京）一带。明清两代也有杂剧，但每本不限四折。散曲，盛行于元、明、清三代的没有宾白的曲子形式。内容以抒情为主，有小令和散套两种。</p><p>元曲原本来自所谓的&quot;蕃曲&quot;&quot;胡乐&quot;，首先在民间流传，被称为&quot;街市小令&quot;或&quot;村坊小调&quot;。随着元灭宋入主中原，它先后在大都（今北京）和临安（今杭州）为中心的南北广袤地区流传开来。元曲有严密的格律定式，每一曲牌的句式、字数、平仄等都有固定的格式要求。虽有定格，但并不死板，允许在定格中加衬字，部分曲牌还可增句，押韵上允许平仄通押，与律诗绝句和宋词相比，有较大的灵活性。</p><h2 id="马致远" tabindex="-1">马致远 <a class="header-anchor" href="#马致远" aria-label="Permalink to &quot;马致远&quot;">​</a></h2><h3 id="天净沙·秋思" tabindex="-1">天净沙·秋思 <a class="header-anchor" href="#天净沙·秋思" aria-label="Permalink to &quot;天净沙·秋思&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/1.html">查看详情</a></strong></p><p>枯藤老树昏鸦，小桥流水人家，古道西风瘦马。 夕阳西下，断肠人在天涯。</p><h3 id="寿阳曲·远浦帆归" tabindex="-1">寿阳曲·远浦帆归 <a class="header-anchor" href="#寿阳曲·远浦帆归" aria-label="Permalink to &quot;寿阳曲·远浦帆归&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/2.html">查看详情</a></strong></p><p>夕阳下，酒旆闲，两三航未曾着岸。 落花水香茅舍晚，断桥头卖鱼人散。</p><h3 id="寿阳曲·潇湘夜雨" tabindex="-1">寿阳曲·潇湘夜雨 <a class="header-anchor" href="#寿阳曲·潇湘夜雨" aria-label="Permalink to &quot;寿阳曲·潇湘夜雨&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/3.html">查看详情</a></strong></p><p>渔灯暗，客梦回，一声声滴人心碎。 孤舟五更家万里，是离人几行情泪。</p><h3 id="寿阳曲·山市晴岚" tabindex="-1">寿阳曲·山市晴岚 <a class="header-anchor" href="#寿阳曲·山市晴岚" aria-label="Permalink to &quot;寿阳曲·山市晴岚&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/4.html">查看详情</a></strong></p><p>花村外，草店西，晚霞明雨收天霁。 四围山一竿残照里，锦屏风又添铺翠。</p><h2 id="张养浩" tabindex="-1">张养浩 <a class="header-anchor" href="#张养浩" aria-label="Permalink to &quot;张养浩&quot;">​</a></h2><h3 id="山坡羊·潼关怀古" tabindex="-1">山坡羊·潼关怀古 <a class="header-anchor" href="#山坡羊·潼关怀古" aria-label="Permalink to &quot;山坡羊·潼关怀古&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/5.html">查看详情</a></strong></p><p>峰峦如聚，波涛如怒，山河表里潼关路。 望西都，意踌躇。 伤心秦汉经行处，宫阙万间都做了土。 兴，百姓苦；亡，百姓苦。</p><h3 id="山坡羊·骊山怀古" tabindex="-1">山坡羊·骊山怀古 <a class="header-anchor" href="#山坡羊·骊山怀古" aria-label="Permalink to &quot;山坡羊·骊山怀古&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/6.html">查看详情</a></strong></p><p>骊山四顾，阿房一炬，当时奢侈今何处？ 只见草萧疏，水萦纡。 至今遗恨迷烟树。列国周齐秦汉楚， 赢，都变做了土；输，都变做了土。</p><h2 id="白朴" tabindex="-1">白朴 <a class="header-anchor" href="#白朴" aria-label="Permalink to &quot;白朴&quot;">​</a></h2><h3 id="天净沙·春" tabindex="-1">天净沙·春 <a class="header-anchor" href="#天净沙·春" aria-label="Permalink to &quot;天净沙·春&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/1.html">查看详情</a></strong></p><p>春山暖日和风，阑干楼阁帘栊，杨柳秋千院中。 啼莺舞燕，小桥流水飞红。</p><h3 id="天净沙·秋" tabindex="-1">天净沙·秋 <a class="header-anchor" href="#天净沙·秋" aria-label="Permalink to &quot;天净沙·秋&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/2.html">查看详情</a></strong></p><p>孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下。 青山绿水，白草红叶黄花。</p><h3 id="沉醉东风·渔夫" tabindex="-1">沉醉东风·渔夫 <a class="header-anchor" href="#沉醉东风·渔夫" aria-label="Permalink to &quot;沉醉东风·渔夫&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/3.html">查看详情</a></strong></p><p>黄芦岸白蘋渡口，绿柳堤红蓼滩头。 虽无刎颈交，却有忘机友， 点秋江白鹭沙鸥。 傲杀人间万户侯，不识字烟波钓叟。</p><h2 id="关汉卿" tabindex="-1">关汉卿 <a class="header-anchor" href="#关汉卿" aria-label="Permalink to &quot;关汉卿&quot;">​</a></h2><h3 id="四块玉·别情" tabindex="-1">四块玉·别情 <a class="header-anchor" href="#四块玉·别情" aria-label="Permalink to &quot;四块玉·别情&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/4.html">查看详情</a></strong></p><p>自送别，心难舍，一点相思几时绝？ 凭阑袖拂杨花雪。 溪又斜，山又遮，人去也！</p><h3 id="大德歌·春" tabindex="-1">大德歌·春 <a class="header-anchor" href="#大德歌·春" aria-label="Permalink to &quot;大德歌·春&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/5.html">查看详情</a></strong></p><p>子规啼，不如归，道是春归人未归。 几日添憔悴，虚飘飘柳絮飞。 一春鱼雁无消息，则见双燕斗衔泥。</p><h2 id="王实甫" tabindex="-1">王实甫 <a class="header-anchor" href="#王实甫" aria-label="Permalink to &quot;王实甫&quot;">​</a></h2><h3 id="十二月过尧民歌·别情" tabindex="-1">十二月过尧民歌·别情 <a class="header-anchor" href="#十二月过尧民歌·别情" aria-label="Permalink to &quot;十二月过尧民歌·别情&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/6.html">查看详情</a></strong></p><p>自别后遥山隐隐，更那堪远水粼粼。 见杨柳飞绵滚滚，对桃花醉脸醺醺。 透内阁香风阵阵，掩重门暮雨纷纷。</p><p>怕黄昏忽地又黄昏，不销魂怎地不销魂。 新啼痕压旧啼痕，断肠人忆断肠人。 今春，香肌瘦几分，缕带宽三寸。</p><h2 id="张可久" tabindex="-1">张可久 <a class="header-anchor" href="#张可久" aria-label="Permalink to &quot;张可久&quot;">​</a></h2><h3 id="卖花声·怀古" tabindex="-1">卖花声·怀古 <a class="header-anchor" href="#卖花声·怀古" aria-label="Permalink to &quot;卖花声·怀古&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/1.html">查看详情</a></strong></p><p>阿房舞殿翻罗袖，金谷名园起玉楼，隋堤古柳缆龙舟。 不堪回首，东风还又，野花开暮春时候。</p><p>美人自刎乌江岸，战火曾烧赤壁山，将军空老玉门关。 伤心秦汉，生民涂炭，读书人一声长叹。</p><h3 id="人月圆·山中书事" tabindex="-1">人月圆·山中书事 <a class="header-anchor" href="#人月圆·山中书事" aria-label="Permalink to &quot;人月圆·山中书事&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/2.html">查看详情</a></strong></p><p>兴亡千古繁华梦，诗眼倦天涯。 孔林乔木，吴宫蔓草，楚庙寒鸦。</p><p>数间茅舍，藏书万卷，投老村家。 山中何事？松花酿酒，春水煎茶。</p><h2 id="乔吉" tabindex="-1">乔吉 <a class="header-anchor" href="#乔吉" aria-label="Permalink to &quot;乔吉&quot;">​</a></h2><h3 id="水仙子·寻梅" tabindex="-1">水仙子·寻梅 <a class="header-anchor" href="#水仙子·寻梅" aria-label="Permalink to &quot;水仙子·寻梅&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/3.html">查看详情</a></strong></p><p>冬前冬后几村庄，溪北溪南两履霜，树头树底孤山上。 冷风来何处香？忽相逢缟袂绡裳。 酒醒寒惊梦，笛凄春断肠，淡月昏黄。</p><h3 id="天净沙·即事" tabindex="-1">天净沙·即事 <a class="header-anchor" href="#天净沙·即事" aria-label="Permalink to &quot;天净沙·即事&quot;">​</a></h3><p><strong><a href="/books/shici/yuanqu/4.html">查看详情</a></strong></p><p>莺莺燕燕春春，花花柳柳真真。 事事风风韵韵。 娇娇嫩嫩，停停当当人人。</p><h2 id="艺术特色" tabindex="-1">艺术特色 <a class="header-anchor" href="#艺术特色" aria-label="Permalink to &quot;艺术特色&quot;">​</a></h2><p>元曲的艺术特色主要体现在以下几个方面：</p><ol><li><strong>语言通俗</strong>：大量使用口语、俗语，通俗易懂</li><li><strong>形式灵活</strong>：句式长短不拘，可加衬字，较为自由</li><li><strong>题材广泛</strong>：既有怀古咏史，又有山水田园、爱情离别</li><li><strong>风格多样</strong>：既有豪放雄浑，又有清新婉约</li><li><strong>音乐性强</strong>：注重音律和谐，适合演唱</li></ol><h2 id="影响与价值" tabindex="-1">影响与价值 <a class="header-anchor" href="#影响与价值" aria-label="Permalink to &quot;影响与价值&quot;">​</a></h2><p>元曲在中国文学史上占有重要地位：</p><ul><li><strong>文学地位</strong>：与唐诗、宋词并称，是中国文学史上的三座高峰</li><li><strong>戏曲源头</strong>：为中国戏曲的发展奠定了基础</li><li><strong>语言贡献</strong>：丰富了汉语的表现力，许多作品成为经典</li><li><strong>文化价值</strong>：反映了元代社会生活的各个方面</li></ul>',68)])])}const q=o(h,[["render",i]]);export{c as __pageData,q as default};
